  "workflows": [
    {
      "frameIds": [
        "f1",
        "f3"
      ],
      "title": "合同/协议审阅与修订",
      "trigger": "需要审阅合同或协议并输出修订版本时",
      "inputs": [
        "待审阅合同/协议文件",
        "审阅视角/立场",
        "修订范围/原则要求"
      ],
      "steps": [
        {
          "id": "s1",
          "methodIds": [
            "m1",
            "m4"
          ],
          "action": "解析文件并根据指定视角识别风险事项",
          "condition": "m1: 通用/指定视角; m4: 弱势供应商视角及最小化修订原则",
          "completionCheck": "输出风险事项列表及分级，或核心风险列表及修订策略"
        },
        {
          "id": "s2",
          "methodIds": [
            "m2",
            "m5"
          ],
          "action": "根据识别结果生成带修订痕迹/标记的文件及说明",
          "condition": "m2: 风险事项已识别; m5: 修订策略已制定",
          "completionCheck": "生成包含修订痕迹和批注的文件，或带修订标记的文件及说明文档"
        }
      ],
      "outputs": [
        "带修订和批注/标记的合同/协议文件",
        "风险分级说明/修订说明与谈判建议"
      ],
      "parameters": [
        "审阅视角",
        "修订范围/原则",
        "合同/协议文件"
      ],
      "conditions": [
        "用户指定了审阅视角和修订范围/原则"
      ],
      "dependencies": [],
      "limitations": [
        "业务效果未知"
      ],
      "includedMethodIds": [
        "m1",
        "m2",
        "m4",
        "m5"
      ]
    },
    {
      "frameIds": [
        "f2",
        "f4"
      ],
      "title": "特定条款调整与文件更新",
      "trigger": "需要根据业务背景或选定方案调整特定条款并更新文件时",
      "inputs": [
        "当前合同/协议版本",
        "补充的业务背景/用户选择的修订方案",
        "需调整的目标条款"
      ],
      "steps": [
        {
          "id": "s1",
          "methodIds": [
            "m3",
            "m6"
          ],
          "action": "根据业务背景设计兼容方案或应用选定方案修改特定条款",
          "condition": "m3: 业务背景与现有条款存在冲突; m6: 用户已选择修订方案",
          "completionCheck": "输出修改/更新后的条款文本及更新后的文件"
        }
      ],
      "outputs": [
        "修改/更新后的条款文本",
        "更新后的合同/协议文件"
      ],
      "parameters": [
        "业务背景/修订方案",
        "目标条款"
      ],
      "conditions": [
        "用户提供了补充业务背景或明确选择了修订方案",
        "现有条款存在冲突或需调整"
      ],
      "dependencies": [],
      "limitations": [
        "业务效果未知"
      ],
      "includedMethodIds": [
        "m3",
        "m6"
      ]
    },
    {
      "frameIds": [
        "f5"
      ],
      "title": "特定条款修改文本单独输出",
      "trigger": "用户要求仅单独输出特定条款的修改文本而不重新生成完整文件时",
      "inputs": [
        "目标条款的修改内容",
        "输出格式要求"
      ],
      "steps": [
        {
          "id": "s1",
          "methodIds": [
            "m7"
          ],
          "action": "提取特定条款的修改内容并按要求格式化输出",
          "condition": "用户要求单独输出修改文本",
          "completionCheck": "输出特定条款的修改文本"
        }
      ],
      "outputs": [
        "特定条款的修改文本"
      ],
      "parameters": [
        "目标条款"
      ],
      "conditions": [
        "用户要求单独输出修改文本"
      ],
      "dependencies": [],
      "limitations": [
        "业务效果未知"
      ],
      "includedMethodIds": [
        "m7"
      ]
    }
  ],
  "ledger": [
    {
      "methodId": "m1",
      "disposition": "INCLUDED",
      "reason": "基于用户要求审阅并输出风险分级，适用于通用/指定视角的合同风险识别",
      "duplicateOf": null
    },
    {
      "methodId": "m2",
      "disposition": "INCLUDED",
      "reason": "用户要求直接输出修订和批注意见版本，适用于生成通用修订痕迹和批注文件",
      "duplicateOf": null
    },
    {
      "methodId": "m3",
      "disposition": "INCLUDED",
      "reason": "用户要求修改排他条款以兼容特定业务背景，适用于根据业务背景设计兼容方案并修改条款",
      "duplicateOf": null
    },
    {
      "methodId": "m4",
      "disposition": "INCLUDED",
      "reason": "用户要求站在供应商角度仅修改核心和重大风险，适用于弱势供应商视角的核心风险识别与最小化策略制定",
      "duplicateOf": null
    },
    {
      "methodId": "m5",
      "disposition": "INCLUDED",
      "reason": "用户要求直接以修订模式进行修改并输出，适用于生成最小化修订标记文件及说明文档",
      "duplicateOf": null
    },
    {
      "methodId": "m6",
      "disposition": "INCLUDED",
      "reason": "用户要求采用选定方案修改特定条款，适用于应用用户选定的修订方案更新条款及文件",
      "duplicateOf": null
    },
    {
      "methodId": "m7",
      "disposition": "INCLUDED",
      "reason": "用户要求不需要重新输出文件，单独输出修改文本，适用于提取并格式化输出特定条款修改内容",
      "duplicateOf": null
    }
  ]
}
